import{_ as t,o as l,c as s,a3 as r,j as e,a as n}from"./chunks/framework.z_KJ15Ep.js";const a="/bilder/suchen-gruppenprozesse/auswahl-filter-i.png",u="/bilder/suchen-gruppenprozesse/auswahl-filter-i-2.png",h="/bilder/suchen-gruppenprozesse/auswahl-filter-i-4.png",d="/bilder/suchen-gruppenprozesse/auswahl-filter-i-5.png",S=JSON.parse('{"title":"Schüler mit kombinierten Filterbedingungen auswählen","description":"","frontmatter":{"title":"Schüler mit kombinierten Filterbedingungen auswählen","source_pageid":290,"source_revision":4778},"headers":[],"relativePath":"schild3/suchen-gruppenprozesse/benutzung-des-schuelerfilters-tutorial.md","filePath":"schild3/suchen-gruppenprozesse/benutzung-des-schuelerfilters-tutorial.md"}'),g={name:"schild3/suchen-gruppenprozesse/benutzung-des-schuelerfilters-tutorial.md"};function c(o,i,m,p,f,b){return l(),s("div",null,[...i[0]||(i[0]=[r('<h1 id="schuler-mit-kombinierten-filterbedingungen-auswahlen" tabindex="-1">Schüler mit kombinierten Filterbedingungen auswählen <a class="header-anchor" href="#schuler-mit-kombinierten-filterbedingungen-auswahlen" aria-label="Permalink to &quot;Schüler mit kombinierten Filterbedingungen auswählen&quot;">​</a></h1><p>Stellen Sie Schülergruppen anhand mehrerer Merkmale zusammen. Die Beispiele zeigen Mehrfachauswahlen und die Suche in früheren Lernabschnitten.</p><h2 id="der-schulerfilter" tabindex="-1">Der Schülerfilter <a class="header-anchor" href="#der-schulerfilter" aria-label="Permalink to &quot;Der Schülerfilter&quot;">​</a></h2><p><a href="/bilder/suchen-gruppenprozesse/auswahl-filter-i.png"><img src="'+a+'" alt="Karteireiter &#39;Schülerfilter in Auswahl." loading="lazy"></a></p><p><em>Karteireiter &#39;Schülerfilter in Auswahl.</em></p><p>Diese Anleitung erläutert die Benutzung des Schülerfilters. Zuerst werden einige grundlegende Informationen gegeben, dann wird die Benutzung anhand von kurzen Beispielen erläutert.</p><p>Der Schülerfilter bietet diverse Selektionsmöglichkeiten, um die gewünschte Schülermenge zu filtern. Der Schülerfilter findet sich unter dem Menüpunkt <strong>Auswahl</strong>.</p><p>Mit dem Schülerfilter wählen Sie Personen nach bestimmten Merkmalen aus. Stellen Sie die Bedingungen zusammen, indem Sie Werte eingeben oder Einträge aus den Auswahllisten wählen.</p><ul><li>Es ist eine Filterung über die Listenfelder der <em>Individualdaten I</em> und <em>Indivdualdaten II</em>, einigen weiteren Daten sowie über den Bereich der <em>Leistungsdaten</em> standardmäßig mit UND-Verknüpfungen, bei einigen Feldern auch mit ODER- Verknüpfungen möglich.</li><li>In vielen Auswahllisten setzen Sie Häkchen vor die gewünschten Einträge. Dabei ist eine Mehrfachauswahl möglich.</li><li>Ein <em>Entfernen</em> gesetzter Filterbedingungen gelingt durch ein erneutes Anklicken des Feldes.</li><li>Es gibt weiterhin Felder, die durch das Anklicken von <em>ja</em> oder <em>nein</em> gefiltert werden. Bei letzteren lässt sich die Auswahl durch das Anwahl des <em>x</em> wieder entfernen</li></ul><p>Grundsätzlich entsprechend die Auswahlmöglichkeiten der Reiter im Filter denen der Reiter in SchILD-NRW:</p><ul><li>Unter <strong>Individualdaten I</strong> können Sie beispielsweise nach <strong>Status</strong>, <strong>Geschlecht</strong>, <strong>Staatsangehörigkeit</strong>, <strong>Aufnahmedatum</strong>, <strong>Klassenart</strong> oder <strong>Prüfungsordnung</strong> filtern.</li><li>Entsprechend finden sich unter <strong>Individualdaten II</strong> stehen Filtermöglichkeiten zum <em>Migrationshintergrund</em>, zum <em>Grundschulbereich</em>, zur <em>Sekundarstufe I</em> und zur <em>sonderpädagogischen Förderung</em> bereit.</li><li>Die <em>Weiteren Daten</em> stellen Auswahlfilter zu den Erziehungsberechtigten und zu Vermerken zur Verfügung. Dort kann ebenfalls nach den Schulbesuchsdaten (zuletzt besuchte Schule, Entlassung von eigener Schule, Wechsel zu aufnehmender Schule) gefiltert werden.</li><li>Unter <strong>Leistungsdaten</strong> filtern Sie beispielsweise nach Schuljahr, Jahrgang, Klasse, Klassenleitung, Abschlussart oder Versetzungsvermerk. Ein Beispiel folgt weiter unten.</li><li>Darüber hinaus gibt es die Möglichkeiten unter dem Reiter <em>KAoA</em> nach bestimmten Maßnahmen der letzten Halbjahre zu suchen</li><li>Unter <em>DSGVO-Einwilligungen</em> stehen die unterschiedlichen Einwilligungen der Datenschutz-Abfragen zur Verfügung. Hier kann der Eintrag bei den Schülerinnen und Schülern entweder ignoriert oder die gefiltert werden, bei denen eine Zustimmung bzw. eine Ablehnung gesucht wird.</li></ul><h3 id="mehrfachauswahlen" tabindex="-1">Mehrfachauswahlen <a class="header-anchor" href="#mehrfachauswahlen" aria-label="Permalink to &quot;Mehrfachauswahlen&quot;">​</a></h3><p><a href="/bilder/suchen-gruppenprozesse/auswahl-filter-i-2.png"><img src="'+u+'" alt="Mehrfachauswahl für komplexere Filterbedingungen treffen." loading="lazy"></a></p><p><em>Mehrfachauswahl für komplexere Filterbedingungen treffen.</em></p>',14),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,[n("Der rote Pfeil kennzeichnet eine Mehrfachauswahl. Wählen Sie einen Eintrag und klicken Sie auf den Pfeil, um ihn zu übernehmen. Wiederholen Sie dies für weitere Einträge. Zum Entfernen klicken Sie mit der rechten Maustaste auf einen ausgewählten Eintrag und wählen "),e("strong",null,"Eintrag löschen"),n(".")])],-1),r('<p><a href="/bilder/suchen-gruppenprozesse/auswahl-filter-i-4.png"><img src="'+h+'" alt="Filterabfragen negieren, um Felder zu suchen, auf welche die Bedingung nicht zutrifft." loading="lazy"></a></p><p><em>Filterabfragen negieren, um Felder zu suchen, auf welche die Bedingung nicht zutrifft.</em></p><p>Doppelklicken Sie auf eine Bedingung, um deren Gegenteil zu suchen. Dieser Vorgang heißt <strong>Negieren</strong>. Die Bedingung wird anschließend <strong>fett</strong> und <em>kursiv</em> dargestellt.</p><p>Die Abbildung zeigt zum Beispiel die Filterung von Schülerinnen und Schüler, die <em>weder evangelisch noch katholisch</em> sind.</p><p>Dementsprechend können z.B. alle Schülerinnen und Schüler gefiltert werden, die nicht in der 3a sind sind oder auch alle, die keine deutsche Staatsangehörigkeit haben usw.</p><h3 id="suche-nach-inhalten-vergangener-lernabschnitte" tabindex="-1">Suche nach Inhalten vergangener Lernabschnitte <a class="header-anchor" href="#suche-nach-inhalten-vergangener-lernabschnitte" aria-label="Permalink to &quot;Suche nach Inhalten vergangener Lernabschnitte&quot;">​</a></h3><p><a href="/bilder/suchen-gruppenprozesse/auswahl-filter-i-5.png"><img src="'+d+'" alt="Filterung auf einen bestimmten Abschluss bei einem ehemaligen Jahrgang." loading="lazy"></a></p><p><em>Filterung auf einen bestimmten Abschluss bei einem ehemaligen Jahrgang.</em></p><p>Ein weiterer häufig genutzter Fall ist das Suchen nach Informationen aus vergangenen Halb- bzw. Schuljahren.</p><p>Unter <strong>Lernabschnitt/Leistungsdaten</strong> können Sie auch frühere Zeiträume auswählen. Das Beispiel sucht Personen, die im zweiten Halbjahr 2020/21 mit einem Hauptschulabschluss nach Klasse 10 abgegangen sind. Unter <strong>Individualdaten I</strong> ist ihr Status <strong>Abschluss</strong>. Die Jahresangabe und die Abschlussbezeichnung gehören zu diesem älteren Beispiel.</p><p>Klicken Sie auf <strong>Testen</strong>, um die zusammengestellten Bedingungen zu prüfen. Mit <strong>Übernehmen</strong> wenden Sie den Filter auf die Schülerauswahl an. Speichern Sie ihn bei Bedarf für eine spätere Verwendung.</p><hr><h2 id="videotutorial-zum-schulerfilter" tabindex="-1">Videotutorial zum Schülerfilter <a class="header-anchor" href="#videotutorial-zum-schulerfilter" aria-label="Permalink to &quot;Videotutorial zum Schülerfilter&quot;">​</a></h2>',13),e("iframe",{"data-extension":"youtube",width:"560",height:"315",src:"//www.youtube-nocookie.com/embed/Scrgk2y0w9s?",frameborder:"0",allowfullscreen:""},null,-1),e("hr",null,null,-1),e("p",null,[e("a",{href:"https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Benutzung_des_Sch%C3%BClerfilters_(Tutorial)",target:"_blank",rel:"noreferrer"},"Originalartikel im Wiki"),n(" · Quellrevision 4778.")],-1)])])}const z=t(g,[["render",c]]);export{S as __pageData,z as default};
